test("Semio video canonical timestamps, denominator, ownership, ordering and controls",async()=>{const d=await semioVideoSnapshotToSqliteDatabase(input);for(const mutate of [(x:any)=>x.tables[1].rows[0].values[8]=0n,(x:any)=>x.tables[2].rows[0].values[3]="018446744073709551615",(x:any)=>x.tables[2].rows[0].values[3]="18446744073709551616",(x:any)=>x.tables[2].rows[0].values[1]=99n,(x:any)=>x.tables[2].rows[0].values[2]=99n]){const x=structuredClone(d);mutate(x);expect(semioVideoSnapshotFromSqliteDatabase(x)).rejects.toThrow();}expect(semioVideoSnapshotToSqliteDatabase({...input,streams:[{...input.streams[0]!,rate:{num:1n,den:0n}}]})).rejects.toThrow();expect(semioVideoSnapshotToSqliteDatabase(input,{maxRows:1})).rejects.toThrow();expect(semioVideoSnapshotFromSqliteDatabase(d,{maxValueBytes:1})).rejects.toThrow();const c=new AbortController();c.abort();expect(semioVideoSnapshotToSqliteDatabase(input,{signal:c.signal})).rejects.toThrow();});

test("Semio video native admission frontier retains independent unsigned timestamp words",()=>{const db=new Database(":memory:");const bytes=Buffer.alloc(8);bytes.writeBigUInt64LE(BigInt(f.timestamp));try{db.run("CREATE TABLE samples(ordinal INTEGER PRIMARY KEY,timestamp TEXT,data BLOB)");for(let ordinal=0;ordinal<f.nativeAdmission.collectionItems;ordinal++)db.query("INSERT INTO samples VALUES(?,?,?)").run(ordinal,bytes.readBigUInt64LE().toString(),Uint8Array.from([0,255]));expect(db.query("SELECT count(*) count FROM samples").get()).toEqual({count:f.nativeAdmission.collectionItems});expect(db.query("SELECT timestamp,hex(data) data FROM samples WHERE ordinal=?").get(f.nativeAdmission.cancelAfter)).toEqual({timestamp:f.timestamp,data:"00FF"});}finally{db.close();}});

